/**
 * ATS lab mock resume (VIBE_DIST=ats-lab only).
 *
 * A one-page PDF for "Taylor Example", generated by e2e/ats-lab tooling and
 * embedded here so the lab content script needs no network and no
 * web_accessible_resources. It contains no real person's data.
 */

export const LAB_RESUME_FILE_NAME = 'Taylor-Example-Resume.pdf';

const LAB_RESUME_PDF_BASE64 =
  '';

function decodeBase64(text: string): Uint8Array<ArrayBuffer> {
  const binary = atob(text);
  const bytes = new Uint8Array(new ArrayBuffer(binary.length));
  for (let index = 0; index < binary.length; index += 1) bytes[index] = binary.charCodeAt(index);
  return bytes;
}

export function labResumeBytes(): Uint8Array<ArrayBuffer> {
  return decodeBase64(LAB_RESUME_PDF_BASE64);
}

export function labResumeFile(): File {
  return new File([labResumeBytes()], LAB_RESUME_FILE_NAME, { type: 'application/pdf' });
}
